{"cards": [{"node_code": "N_5a2a2890136a54df", "definition": "针对港口及进港航道冰情，研究破冰船作业、冰层监测、防冰设施维护及冰害预防的技术领域，旨在保障冬季通航安全。", "boundary": "本节点聚焦于“冰”对港口通航的影响及应对。边界在于区分“破冰作业”（主动清除冰层）与“水深维护”（疏浚泥沙）。若内容涉及船舶抗冰结构设计，归入船舶工程；若涉及港口整体防冻规划，可关联总体规划。本节点侧重运维阶段的冰情处理与设施保护。", "includes": ["港口航道破冰船作业技术与组织", "冰情监测、预报及防冰设施（如冰坝）维护", "冰害对港口水工建筑物的损害机理及预防措施"], "excludes": ["船舶船体抗冰结构设计", "非港口区域的海洋或内河通用破冰研究", "港口新建工程中的防冰设计"], "sibling_distinctions": [{"other_code": "N_d750edbf3bdf8341", "rule": "破冰工作针对冰层障碍，水深维护针对泥沙淤积；两者均为通航保障，但介质与手段不同。"}, {"other_code": "N_d5faec265ce374e9", "rule": "破冰工作侧重主动清除冰层以保通航，损害和预防侧重冰对建筑物结构的破坏及防护。"}, {"other_code": "N_285c153e3ade67cf", "rule": "破冰工作针对冰情，建筑物维修针对结构病害；若冰导致结构损坏，修复归维修，除冰归破冰。"}], "cross_boundary_rule": "若内容涉及破冰船本身的设计制造，主挂载船舶工程；若涉及港口水域冰情下的通航组织与除冰作业，主挂载本节点。"}, {"node_code": "N_d750edbf3bdf8341", "definition": "研究港口池、进港航道及锚地的泥沙淤积规律，实施疏浚、吹填及防淤措施，以维持设计水深和通航能力的技术领域。", "boundary": "本节点聚焦于“水深”这一通航要素的维护。边界在于区分“疏浚工程”（新建）与“维护性疏浚”（本节点）。若内容涉及航道整治工程（如裁弯取直），归入航道工程；若涉及港口陆域吹填造地，侧重土地开发可关联港口规划，侧重水域维护归本节点。", "includes": ["港池及航道的定期疏浚与清淤技术", "泥沙淤积监测、预测及防淤护岸措施", "维护性吹填及水深达标检测技术"], "excludes": ["新建港口的初始疏浚工程", "非港口区域的通用航道整治工程", "港口陆域土地开发工程（若未涉及水域维护）"], "sibling_distinctions": [{"other_code": "N_5a2a2890136a54df", "rule": "水深维护针对泥沙，破冰工作针对冰层；两者共同保障通航条件，但处理对象不同。"}, {"other_code": "N_d5faec265ce374e9", "rule": "水深维护侧重水域底泥管理，损害和预防侧重建筑物结构安全；疏浚不当可能引发结构损害，需协同考虑。"}, {"other_code": "N_285c153e3ade67cf", "rule": "水深维护针对水域环境，建筑物维修针对实体结构；疏浚作业可能影响结构稳定，需区分作业对象。"}], "cross_boundary_rule": "若疏浚工程规模巨大且涉及航道线位调整，主挂载航道工程；若为常规维护性疏浚以保港口水深，主挂载本节点。"}, {"node_code": "N_d5faec265ce374e9", "definition": "研究港口水工建筑物在自然荷载、船舶碰撞及环境侵蚀下的病害机理，开展检测评估、预防性维护及结构安全监测的技术领域。", "boundary": "本节点聚焦于“损害”与“预防”，即结构安全的全生命周期管理。边界在于区分“检测预防”（本节点）与“修复施工”（归入港口建筑物的维修）。若内容涉及新建结构的设计安全，归入港口水工建筑物；若涉及具体裂缝修补工艺，归入维修。本节点侧重诊断、评估与预防策略。", "includes": ["码头、防波堤等建筑物的病害检测与评估技术", "结构安全监测、预警系统及预防性维护策略", "船舶碰撞、波浪冲击等荷载下的损害机理研究"], "excludes": ["具体的结构修复、加固施工工艺", "新建水工建筑物的结构设计与计算", "港口运营中的货物损坏或安全事故处理"], "sibling_distinctions": [{"other_code": "N_285c153e3ade67cf", "rule": "损害和预防侧重“诊断”与“防”，即发现病害和防止病害发生；建筑物维修侧重“治”，即对已发生病害进行修复。"}, {"other_code": "N_5a2a2890136a54df", "rule": "损害和预防涵盖所有荷载（冰、浪、船碰等）下的结构安全，破冰工作仅针对冰情；冰害预防可交叉，但结构综合评估归本节点。"}, {"other_code": "N_d750edbf3bdf8341", "rule": "损害和预防关注结构本体安全，水深维护关注水域通航条件；疏浚作业需评估对结构的影响，但对象不同。"}], "cross_boundary_rule": "若内容涉及检测后直接进行的修复方案实施，主挂载港口建筑物的维修；若侧重检测技术、评估标准及预防体系，主挂载本节点。"}]}
